body.script:
//
document.addEventListener('DOMContentLoaded', function () {
  var toggle = document.querySelector('.menu-toggle');
  var nav = document.querySelector('nav.primary');
  if (toggle && nav) {
    toggle.addEventListener('click', function () {
      nav.classList.toggle('open');
    });
  }

  // Hide the post body's own copy of the image when Blogger already shows
  // a featured-image banner above the article. Do not compare URLs here:
  // Blogger may proxy/normalize externally hosted images. Instead, inspect
  // only the first meaningful content block and hide it when it is an
  // image-only block. This covers Blogger-native markup and generated posts
  // such as <article class="zv-blog-post"><p><img ...></p>...</article>.
  var heroImg = document.querySelector('.post-single-image img');
  var bodyEl = document.querySelector('.post-single-body');

  function firstMeaningfulElement(root) {
    if (!root) return null;
    var children = root.children;
    for (var i = 0; i < children.length; i++) {
      var el = children[i];
      if (el.matches('script, style')) continue;
      if ((el.textContent || '').trim() === '' && !el.querySelector('img') && el.tagName !== 'IMG') continue;
      return el;
    }
    return null;
  }

  function isImageOnlyBlock(el) {
    if (!el) return false;
    if (el.tagName === 'IMG') return true;
    var imgs = el.querySelectorAll('img');
    if (imgs.length !== 1) return false;

    // Clone the block, remove non-visible/auxiliary elements and the image,
    // then ensure no real text remains. This prevents hiding an introductory
    // paragraph that merely happens to contain an image.
    var clone = el.cloneNode(true);
    var removable = clone.querySelectorAll('img, script, style, noscript');
    for (var i = 0; i < removable.length; i++) removable[i].remove();
    return (clone.textContent || '').replace(/\s+/g, '').length === 0;
  }

  if (heroImg && bodyEl) {
    var contentRoot = bodyEl.querySelector(':scope > .zv-blog-post') || bodyEl;
    var first = firstMeaningfulElement(contentRoot);
    if (isImageOnlyBlock(first)) {
      first.style.display = 'none';
      first.setAttribute('data-zv-featured-duplicate', 'hidden');
    }
  }

  // Homepage Latest Posts: extract the actual editorial intro from the post HTML.
  // Prefer .post-intro (new post standard); for legacy posts use the first
  // meaningful paragraph inside .zv-blog-post. This deliberately ignores
  // embedded style blocks/comments that can pollute Blogger's generated snippet.
  if (document.body.classList.contains('zv-homepage')) {
    var homeRows = document.querySelectorAll('.post-row');
    for (var hi = 0; hi < homeRows.length; hi++) {
      var row = homeRows[hi];
      var sourceTemplate = row.querySelector('template.home-intro-source');
      var targetIntro = row.querySelector('.home-intro-text');
      if (!sourceTemplate || !targetIntro) continue;

      var root = sourceTemplate.content || sourceTemplate;
      var introNode = root.querySelector ? root.querySelector('.post-intro') : null;
      var introText = '';

      if (introNode) {
        introText = (introNode.textContent || '').replace(/\s+/g, ' ').trim();
      }

      if (!introText && root.querySelectorAll) {
        var paragraphScope = root.querySelector('.zv-blog-post') || root;
        var paragraphs = paragraphScope.querySelectorAll('p');
        for (var hp = 0; hp < paragraphs.length; hp++) {
          var candidate = (paragraphs[hp].textContent || '').replace(/\s+/g, ' ').trim();
          if (candidate) {
            introText = candidate;
            break;
          }
        }
      }

      // Final safety fallback for unusual legacy markup.
      if (!introText) {
        var fallback = row.querySelector('.post-body');
        introText = fallback ? (fallback.getAttribute('data-fallback-intro') || '') : '';
      }

      targetIntro.textContent = introText;
      if (!introText) targetIntro.style.display = 'none';
    }
  }

  // Homepage Hero carousel: fetch the latest three posts with the structural
  // Blogger label "Hero". The carousel is manual-only (no auto-rotation).
  // The same URLs are then excluded from Latest Posts to prevent duplication.
  if (document.body.classList.contains('zv-homepage')) {
    var heroCarousel = document.getElementById('hero-carousel');
    var heroTrack = document.getElementById('hero-carousel-track');
    var heroControls = document.getElementById('hero-carousel-controls');
    var heroDots = document.getElementById('hero-carousel-dots');
    var heroUrls = {};

    function heroEscape(value) {
      var div = document.createElement('div');
      div.textContent = value == null ? '' : String(value);
      return div.innerHTML;
    }

    function heroEntryUrl(entry) {
      var links = entry.link || [];
      for (var i = 0; i < links.length; i++) {
        if (links[i].rel === 'alternate') return links[i].href;
      }
      return '';
    }

    function heroContentHtml(entry) {
      if (entry.content && entry.content.$t) return entry.content.$t;
      if (entry.summary && entry.summary.$t) return entry.summary.$t;
      return '';
    }

    function heroIntroAndImage(entry) {
      var html = heroContentHtml(entry);
      var holder = document.createElement('div');
      holder.innerHTML = html;

      var intro = holder.querySelector('.post-intro');
      var introText = intro ? (intro.textContent || '').replace(/\s+/g, ' ').trim() : '';

      if (!introText) {
        var scope = holder.querySelector('.zv-blog-post') || holder;
        var ps = scope.querySelectorAll('p');
        for (var p = 0; p < ps.length; p++) {
          var candidate = (ps[p].textContent || '').replace(/\s+/g, ' ').trim();
          if (candidate) {
            introText = candidate;
            break;
          }
        }
      }

      var image = '';
      if (entry.media$thumbnail && entry.media$thumbnail.url) {
        image = entry.media$thumbnail.url.replace(/\/s72-c\//, '/s900/');
      }
      if (!image) {
        var img = holder.querySelector('img');
        if (img) image = img.getAttribute('src') || '';
      }

      return { intro: introText, image: image };
    }

    function heroDate(entry) {
      var raw = entry.published && entry.published.$t ? entry.published.$t : '';
      var d = raw ? new Date(raw) : null;
      if (!d || isNaN(d.getTime())) return '';
      try {
        return new Intl.DateTimeFormat('en', {
          month: 'long',
          day: '2-digit',
          year: 'numeric'
        }).format(d);
      } catch (e) {
        return d.toDateString();
      }
    }

    function updateLatestPostsAfterHero() {
      // Latest Posts intentionally shows the actual four newest posts.
      // Hero membership does not remove a post from this section.
      var rows = document.querySelectorAll('.latest-posts-list .post-row');
      for (var r = 0; r < rows.length; r++) {
        rows[r].style.display = r < 4 ? '' : 'none';
      }
    }

    function initHeroSlides(entries) {
      if (!heroTrack || !entries || !entries.length) {
        if (heroCarousel) heroCarousel.style.display = 'none';
        updateLatestPostsAfterHero();
        return;
      }

      var slidesHtml = '';
      var dotsHtml = '';

      for (var h = 0; h < entries.length; h++) {
        var entry = entries[h];
        var url = heroEntryUrl(entry);
        if (!url) continue;
        heroUrls[url] = true;

        var title = entry.title && entry.title.$t ? entry.title.$t : 'Untitled post';
        var info = heroIntroAndImage(entry);
        var imageHtml = info.image
          ? '<img alt="' + heroEscape(title) + '" src="' + heroEscape(info.image) + '"/>'
          : '<div class="thumb-fill thumb-gold"></div>';

        slidesHtml +=
          '<section class="hero hero-slide' + (h === 0 ? ' is-active' : '') + '" data-hero-index="' + h + '">' +
            '<div class="hero-inner">' +
              '<div class="hero-text">' +
                '<div class="hero-kicker">Hero post</div>' +
                '<h1><a href="' + heroEscape(url) + '">' + heroEscape(title) + '</a></h1>' +
                (info.intro ? '<p class="hero-excerpt">' + heroEscape(info.intro) + '</p>' : '') +
                '<div class="hero-meta">' +
                  '<span class="mono">' + heroEscape(heroDate(entry)) + '</span>' +
                  '<a class="read-link" href="' + heroEscape(url) + '">Read more</a>' +
                '</div>' +
              '</div>' +
              '<div class="hero-image">' + imageHtml + '</div>' +
            '</div>' +
          '</section>';

        dotsHtml += '<button aria-label="Show Hero post ' + (h + 1) + '" class="hero-carousel-dot' +
          (h === 0 ? ' is-active' : '') + '" data-hero-dot="' + h + '" type="button"></button>';
      }

      heroTrack.innerHTML = slidesHtml;
      heroDots.innerHTML = dotsHtml;

      var slides = heroTrack.querySelectorAll('.hero-slide');
      var dots = heroDots.querySelectorAll('.hero-carousel-dot');
      if (!slides.length) {
        heroCarousel.style.display = 'none';
        updateLatestPostsAfterHero();
        return;
      }

      if (slides.length > 1) heroControls.style.display = 'flex';

      var current = 0;
      function showHero(index) {
        current = (index + slides.length) % slides.length;
        for (var s = 0; s < slides.length; s++) {
          slides[s].classList.toggle('is-active', s === current);
          if (dots[s]) dots[s].classList.toggle('is-active', s === current);
        }
      }

      var prev = heroControls.querySelector('.hero-prev');
      var next = heroControls.querySelector('.hero-next');
      if (prev) prev.addEventListener('click', function () { showHero(current - 1); });
      if (next) next.addEventListener('click', function () { showHero(current + 1); });
      for (var d = 0; d < dots.length; d++) {
        (function (dot, dotIndex) {
          dot.addEventListener('click', function () { showHero(dotIndex); });
        })(dots[d], d);
      }

      updateLatestPostsAfterHero();
    }

    if (heroCarousel && heroTrack && window.fetch) {
      fetch('/feeds/posts/default/-/Hero?alt=json&max-results=3', { credentials: 'same-origin' })
        .then(function (response) {
          if (!response.ok) throw new Error('Hero feed HTTP ' + response.status);
          return response.json();
        })
        .then(function (feedData) {
          var entries = feedData && feedData.feed && feedData.feed.entry ? feedData.feed.entry : [];
          initHeroSlides(entries.slice(0, 3));
        })
        .catch(function () {
          heroCarousel.style.display = 'none';
          updateLatestPostsAfterHero();
        });
    } else {
      updateLatestPostsAfterHero();
    }
  }

  // Homepage Latest Series: keep the curated three overview cards, but
  // populate each card with the latest three entries from its own overview post.
  // The overview post remains the single source of truth for series membership/order.
  if (document.body.classList.contains('zv-homepage') && window.fetch) {
    var homeSeriesCards = document.querySelectorAll('#series .series-card');

    function seriesPadNumber(value) {
      return value < 10 ? '0' + value : String(value);
    }

    function updateSeriesCard(card) {
      var overviewLink = card.querySelector('h3 a');
      var progress = card.querySelector('.series-progress');
      if (!overviewLink || !progress) return;

      var overviewUrl = overviewLink.href;

      fetch(overviewUrl, { credentials: 'same-origin' })
        .then(function (response) {
          if (!response.ok) throw new Error('Series overview HTTP ' + response.status);
          return response.text();
        })
        .then(function (htmlText) {
          var parser = new DOMParser();
          var doc = parser.parseFromString(htmlText, 'text/html');
          var overviewItems = doc.querySelectorAll('.zv-blog-post .zv-series-grid .zv-series-card');
          if (!overviewItems.length) return;

          var start = Math.max(0, overviewItems.length - 3);
          var html = '';

          for (var i = start; i < overviewItems.length; i++) {
            var item = overviewItems[i];
            var href = item.getAttribute('href') || '';
            var titleNode = item.querySelector('p');
            var title = titleNode ? titleNode.textContent.trim() : item.textContent.trim();
            if (!href || !title) continue;

            var absoluteHref = new URL(href, overviewUrl).href;
            html += '<div class="part">' +
              '<span class="num mono">' + seriesPadNumber(i + 1) + '</span>' +
              '<a href="' + absoluteHref.replace(/&/g, '&amp;').replace(/"/g, '&quot;') + '">' +
                title.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;') +
              '</a>' +
            '</div>';
          }

          if (html) progress.innerHTML = html;
        })
        .catch(function () {
          // Keep the hard-coded fallback already present in the theme.
        });
    }

    for (var sc = 0; sc < homeSeriesCards.length; sc++) {
      updateSeriesCard(homeSeriesCards[sc]);
    }
  }

  // Homepage Latest Events: load the four newest posts carrying the
  // structural Blogger label "Events" and render compact image + title cards.
  if (document.body.classList.contains('zv-homepage')) {
    var latestEventsList = document.getElementById('latest-events-list');

    function eventEscape(value) {
      var div = document.createElement('div');
      div.textContent = value == null ? '' : String(value);
      return div.innerHTML;
    }

    function eventEntryUrl(entry) {
      var links = entry.link || [];
      for (var i = 0; i < links.length; i++) {
        if (links[i].rel === 'alternate') return links[i].href;
      }
      return '';
    }

    function eventEntryImage(entry) {
      // Prefer the image URL in the post itself. Blogger feed thumbnails can
      // already be a cropped derivative, which cannot be restored by resizing.
      var html = '';
      if (entry.content && entry.content.$t) html = entry.content.$t;
      else if (entry.summary && entry.summary.$t) html = entry.summary.$t;

      if (html) {
        var holder = document.createElement('div');
        holder.innerHTML = html;
        var img = holder.querySelector('img');
        if (img) return img.getAttribute('src') || '';
      }

      // Fall back to a larger, uncropped feed thumbnail for older posts whose
      // body does not contain an image.
      if (entry.media$thumbnail && entry.media$thumbnail.url) {
        return entry.media$thumbnail.url
          .replace(/\/s72-c\//, '/s900/')
          .replace(/=s72-c$/, '=s900');
      }
      return '';
    }

    function renderLatestEvents(entries) {
      if (!latestEventsList) return;

      if (!entries || !entries.length) {
        var empty = latestEventsList.querySelector('.latest-events-empty');
        if (empty) empty.style.display = '';
        return;
      }

      var html = '';
      var count = Math.min(4, entries.length);

      for (var e = 0; e < count; e++) {
        var entry = entries[e];
        var url = eventEntryUrl(entry);
        if (!url) continue;

        var title = entry.title && entry.title.$t ? entry.title.$t : 'Untitled event';
        var image = eventEntryImage(entry);

        html +=
          '<article class="post-row">' +
            '<div class="post-thumb">' +
              (image
                ? '<img alt="' + eventEscape(title) + '" src="' + eventEscape(image) + '"/>'
                : '<div class="thumb-fill thumb-bronze"></div>') +
            '</div>' +
            '<div class="post-body">' +
              '<h3><a href="' + eventEscape(url) + '">' + eventEscape(title) + '</a></h3>' +
            '</div>' +
          '</article>';
      }

      latestEventsList.innerHTML = html;
    }

    if (latestEventsList && window.fetch) {
      fetch('/feeds/posts/default/-/Events?alt=json&max-results=4', { credentials:'same-origin' })
        .then(function (response) {
          if (!response.ok) throw new Error('Events feed HTTP ' + response.status);
          return response.json();
        })
        .then(function (feedData) {
          var entries = feedData && feedData.feed && feedData.feed.entry
            ? feedData.feed.entry
            : [];
          renderLatestEvents(entries);
        })
        .catch(function () {
          var empty = latestEventsList.querySelector('.latest-events-empty');
          if (empty) {
            empty.textContent = 'Events could not be loaded.';
            empty.style.display = '';
          }
        });
    }
  }

  // Turn only the top-level archive years into an accordion. The newest year
  // is expanded by default; older years are collapsed. Year names remain links.
  var archiveTree = document.querySelector('.archive-tree');
  if (archiveTree) {
    var archiveYears = archiveTree.querySelectorAll(':scope > .archive-list > .archive-year');
    for (var ai = 0; ai < archiveYears.length; ai++) {
      (function (year, yearIndex) {
        var yearLink = year.querySelector(':scope > a');
        var months = year.querySelector(':scope > .archive-months');
        if (!yearLink || !months) return;

        year.classList.add('archive-year-top');
        if (yearIndex === 0) year.classList.add('is-open');

        var head = document.createElement('div');
        head.className = 'archive-year-head';
        year.insertBefore(head, yearLink);

        var toggle = document.createElement('button');
        toggle.className = 'archive-year-toggle';
        toggle.type = 'button';
        toggle.setAttribute('aria-label', (yearIndex === 0 ? 'Collapse ' : 'Expand ') + (yearLink.textContent || 'archive year').trim());
        toggle.setAttribute('aria-expanded', yearIndex === 0 ? 'true' : 'false');
        head.appendChild(toggle);
        head.appendChild(yearLink);

        toggle.addEventListener('click', function () {
          var open = year.classList.toggle('is-open');
          toggle.setAttribute('aria-expanded', open ? 'true' : 'false');
          toggle.setAttribute('aria-label', (open ? 'Collapse ' : 'Expand ') + (yearLink.textContent || 'archive year').trim());
        });
      })(archiveYears[ai], ai);
    }
  }

  // Keep the sidebar label cloud compact by default. Blogger supplies labels
  // in FREQUENCY order, so the first 15 are the most-used labels.
  var labelCloud = document.querySelector('.label-cloud');
  var labelToggle = document.querySelector('.label-cloud-toggle');
  if (labelCloud && labelToggle) {
    var labelLinks = labelCloud.querySelectorAll('a');
    if (labelLinks.length <= 15) {
      labelCloud.classList.remove('is-collapsed');
      labelToggle.style.display = 'none';
    } else {
      labelToggle.addEventListener('click', function () {
        var collapsed = labelCloud.classList.toggle('is-collapsed');
        labelToggle.setAttribute('aria-expanded', collapsed ? 'false' : 'true');
        labelToggle.textContent = collapsed ? 'Show all labels' : 'Show top 15';
      });
    }
  }
});

  // Posts / Series / Events list-grid view switch.
  // Defaults are label-specific:
  //   Posts  -> Grid
  //   Series -> List
  //   Events -> List
  // A visitor's explicit choice is remembered separately for each section.
  var contentViewSwitch = document.getElementById('content-view-switch');
  if (contentViewSwitch) {
    var contentList = document.querySelector('.latest-posts-list');
    var contentViewButtons = contentViewSwitch.querySelectorAll('[data-content-view]');

    var pathMatch = window.location.pathname.match(/^\/search\/label\/([^/?#]+)/);
    var currentLabel = pathMatch ? decodeURIComponent(pathMatch[1]) : '';
    var defaultMode = currentLabel === 'Posts' ? 'grid' : 'list';
    var storageKey = 'zv-content-view-' + (currentLabel || 'default').toLowerCase();

    function setContentView(mode, persist) {
      if (mode !== 'grid') mode = 'list';

      if (contentList) {
        contentList.classList.toggle('is-grid-view', mode === 'grid');
      }

      for (var vb = 0; vb < contentViewButtons.length; vb++) {
        var active = contentViewButtons[vb].getAttribute('data-content-view') === mode;
        contentViewButtons[vb].classList.toggle('is-active', active);
        contentViewButtons[vb].setAttribute('aria-pressed', active ? 'true' : 'false');
      }

      if (persist) {
        try { window.localStorage.setItem(storageKey, mode); } catch (e) {}
      }
    }

    var savedContentView = null;
    try { savedContentView = window.localStorage.getItem(storageKey); } catch (e) {}

    setContentView(savedContentView || defaultMode, false);

    for (var vb2 = 0; vb2 < contentViewButtons.length; vb2++) {
      contentViewButtons[vb2].addEventListener('click', function () {
        setContentView(this.getAttribute('data-content-view'), true);
      });
    }
  }

  // Sequential list pagination for Posts / Series / Events / search/archive pages.
  // Blogger's native newerPageUrl may jump directly to the first/newest page,
  // so keep our own per-listing stack for the immediately preceding page.
  // Also validate the native olderPageUrl before showing "More posts" because
  // Blogger can occasionally generate a final link whose target contains no posts.
  var earlierPageLink = document.querySelector('.earlier-page-link');
  var morePageLink = document.querySelector('.more-page-link');

  if (earlierPageLink || morePageLink) {
    try {
      var here = new URL(window.location.href);
      var listingKey = 'zv-pager-stack:' + here.pathname;
      var pagerStack = [];

      try {
        pagerStack = JSON.parse(window.sessionStorage.getItem(listingKey) || '[]');
        if (!Array.isArray(pagerStack)) pagerStack = [];
      } catch (e) {
        pagerStack = [];
      }

      // A clean label/index URL is the first page. Never show Earlier posts there,
      // and reset any stale stack left from an older browsing session.
      var isPaginatedPage =
        here.searchParams.has('updated-max') ||
        here.searchParams.has('start') ||
        here.searchParams.has('page');

      if (!isPaginatedPage) {
        pagerStack = [];
        try { window.sessionStorage.removeItem(listingKey); } catch (e) {}
      }

      if (earlierPageLink && isPaginatedPage && pagerStack.length) {
        var previousUrl = pagerStack[pagerStack.length - 1];
        earlierPageLink.href = previousUrl;
        earlierPageLink.style.display = '';
        earlierPageLink.addEventListener('click', function () {
          pagerStack.pop();
          try {
            window.sessionStorage.setItem(listingKey, JSON.stringify(pagerStack));
          } catch (e) {}
        });
      }

      if (morePageLink) {
        var moreUrl = morePageLink.href;

        function rememberCurrentPage() {
          var currentUrl = window.location.href;
          if (!pagerStack.length || pagerStack[pagerStack.length - 1] !== currentUrl) {
            pagerStack.push(currentUrl);
          }
          try {
            window.sessionStorage.setItem(listingKey, JSON.stringify(pagerStack));
          } catch (e) {}
        }

        // Validate that Blogger's proposed next page really contains at least one
        // listing row. On the final page the link therefore remains hidden.
        if (window.fetch && moreUrl) {
          fetch(moreUrl, { credentials:'same-origin' })
            .then(function (response) {
              if (!response.ok) throw new Error('Pager HTTP ' + response.status);
              return response.text();
            })
            .then(function (html) {
              var parsed = new DOMParser().parseFromString(html, 'text/html');
              var rows = parsed.querySelectorAll('.latest-posts-list .post-row');
              if (rows.length > 0) {
                morePageLink.style.display = '';
                morePageLink.addEventListener('click', rememberCurrentPage);
              }
            })
            .catch(function () {
              // If validation is unavailable, preserve Blogger's native navigation.
              morePageLink.style.display = '';
              morePageLink.addEventListener('click', rememberCurrentPage);
            });
        } else if (moreUrl) {
          morePageLink.style.display = '';
          morePageLink.addEventListener('click', rememberCurrentPage);
        }
      }
    } catch (e) {}
  }

  // Single-post reader enhancements. Generated post HTML remains semantic;
  // the theme adds navigation and interaction at runtime.
  if (document.querySelector('.post-single')) {
    var articleBody = document.querySelector('.post-single-body');
    var toc = document.getElementById('post-toc');
    var tocList = document.getElementById('post-toc-list');
    var progress = document.getElementById('reading-progress');
    var backTop = document.getElementById('back-to-top');

    function slugifyHeading(text) {
      return (text || '')
        .toLowerCase()
        .trim()
        .replace(/[^a-z0-9\s-]/g, '')
        .replace(/\s+/g, '-')
        .replace(/-+/g, '-')
        .replace(/^-|-$/g, '') || 'section';
    }

    // Build TOC only for genuinely structured/longer posts (4+ H2/H3 headings).
    if (articleBody && toc && tocList && !document.body.classList.contains('zv-static-page')) {
      var headings = articleBody.querySelectorAll('h2, h3');
      if (headings.length >= 4) {
        var usedIds = {};
        for (var i = 0; i < headings.length; i++) {
          var heading = headings[i];
          var base = heading.id || slugifyHeading(heading.textContent);
          var id = base;
          var suffix = 2;
          while (usedIds[id] || document.getElementById(id)) {
            if (heading.id === id) break;
            id = base + '-' + suffix++;
          }
          if (!heading.id) heading.id = id;
          usedIds[heading.id] = true;

          var li = document.createElement('li');
          li.className = heading.tagName.toLowerCase() === 'h3' ? 'toc-h3' : 'toc-h2';

          var a = document.createElement('a');
          a.href = '#' + heading.id;
          a.textContent = (heading.textContent || '').trim();

          li.appendChild(a);
          tocList.appendChild(li);
        }
        toc.classList.add('is-visible');
      }
    }

    // Add copy-to-clipboard buttons to code blocks.
    if (articleBody) {
      var pres = articleBody.querySelectorAll('pre');
      for (var p = 0; p < pres.length; p++) {
        (function (pre) {
          if (pre.querySelector('.code-copy')) return;
          var code = pre.querySelector('code');
          if (!code) return;

          var btn = document.createElement('button');
          btn.type = 'button';
          btn.className = 'code-copy';
          btn.textContent = 'Copy';
          btn.setAttribute('aria-label', 'Copy code');

          btn.addEventListener('click', function () {
            var value = code.innerText || code.textContent || '';
            function done() {
              btn.textContent = 'Copied';
              setTimeout(function () { btn.textContent = 'Copy'; }, 1400);
            }
            if (navigator.clipboard && navigator.clipboard.writeText) {
              navigator.clipboard.writeText(value).then(done).catch(function () {});
            } else {
              var ta = document.createElement('textarea');
              ta.value = value;
              ta.style.position = 'fixed';
              ta.style.opacity = '0';
              document.body.appendChild(ta);
              ta.select();
              try { document.execCommand('copy'); done(); } catch (e) {}
              document.body.removeChild(ta);
            }
          });

          pre.appendChild(btn);
        })(pres[p]);
      }
    }

    // Reading progress + back-to-top visibility.
    function updateReaderPosition() {
      var scrollTop = window.pageYOffset || document.documentElement.scrollTop || 0;
      var docHeight = Math.max(
        document.body.scrollHeight,
        document.documentElement.scrollHeight
      );
      var viewport = window.innerHeight || document.documentElement.clientHeight || 1;
      var maxScroll = Math.max(1, docHeight - viewport);
      var pct = Math.max(0, Math.min(100, (scrollTop / maxScroll) * 100));

      if (progress) progress.style.width = pct + '%';
      if (backTop) backTop.classList.toggle('is-visible', scrollTop > viewport * 1.5);
    }

    window.addEventListener('scroll', updateReaderPosition, { passive:true });
    window.addEventListener('resize', updateReaderPosition);
    updateReaderPosition();

    if (backTop) {
      backTop.addEventListener('click', function () {
        window.scrollTo({ top:0, behavior:'smooth' });
      });
    }
  }

